function GuisApi.Utils.GenerateCameraGrid(camType: string)
	local names = replicated.Functions.GetAllCameras:InvokeServer(camType)
	return New("Frame") {
		BackgroundTransparency = 1,
		[Children] = {
			New("UIGridLayout") {
				CellSize = UDim2.fromOffset(100, 30),
			},

