	return New "Frame" {
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		[Children] = {
			New "Frame" {
				AnchorPoint = centerAnchor,
				Position = UDim2.fromScale(0.5, 0),
				Size = horizontalSize,
				BackgroundTransparency = 1,
				Name = "TopCenter",
				[OnEvent "InputBegan"] = function(input)
					props.OnInput(input, "top")
				end,
			},
			New "Frame" {
				AnchorPoint = centerAnchor,
				Position = UDim2.fromScale(1, 0.5),
				Size = verticalSize,
				BackgroundTransparency = 1,
				Name = "MiddleRight",
				[OnEvent "InputBegan"] = function(input)
					props.OnInput(input, "right")
				end,
				[OnEvent "MouseEnter"] = function()
					props.ShowIcon(ICONS.horizontal)
				end,
				[OnEvent "MouseLeave"] = function()
					props.HideIcon()
				end,
			},
			New "Frame" {
				AnchorPoint = centerAnchor,
				Position = UDim2.fromScale(0.5, 1),
				Size = horizontalSize,
				BackgroundTransparency = 1,
				Name = "BottomCenter",
				[OnEvent "InputBegan"] = function(input)
					props.OnInput(input, "bottom")
				end,
				[OnEvent "MouseEnter"] = function()
					props.ShowIcon(ICONS.vertical)
				end,
				[OnEvent "MouseLeave"] = function()
					props.HideIcon()
				end,
			},
			New "Frame" {
				AnchorPoint = centerAnchor,
				Position = UDim2.fromScale(0, 0.5),
				Size = verticalSize,
				BackgroundTransparency = 1,
				Name = "MiddleLeft",
				[OnEvent "InputBegan"] = function(input)
					props.OnInput(input, "left")
				end,
				[OnEvent "MouseEnter"] = function()
					props.ShowIcon(ICONS.horizontal)
				end,
				[OnEvent "MouseLeave"] = function()
					props.HideIcon()
				end,
			},

			New "Frame" {
				BackgroundTransparency = 1,
				AnchorPoint = centerAnchor,
				Position = UDim2.fromScale(0, 0),
				Size = cornerSize,
				Name = "TopLeft",
			},
			New "Frame" {
				BackgroundTransparency = 1,
				AnchorPoint = centerAnchor,
				Position = UDim2.fromScale(1, 0),
				Size = cornerSize,
				Name = "TopRight",
			},
			New "Frame" {
				BackgroundTransparency = 1,
				AnchorPoint = centerAnchor,
				Position = UDim2.fromScale(0, 1),
				Size = cornerSize,
				Name = "BottomLeft",
				[OnEvent "InputBegan"] = function(input)
					props.OnInput(input, "bottomleft")
				end,
				[OnEvent "MouseEnter"] = function()
					props.ShowIcon(ICONS.bottomLeft)
				end,
				[OnEvent "MouseLeave"] = function()
					props.HideIcon()
				end,
			},
			New "Frame" {
				BackgroundTransparency = 1,
				AnchorPoint = centerAnchor,
				Position = UDim2.fromScale(1, 1),
				Size = cornerSize,
				Name = "BottomRight",
				[OnEvent "InputBegan"] = function(input)
					props.OnInput(input, "bottomright")
				end,
				[OnEvent "MouseEnter"] = function()
					props.ShowIcon(ICONS.bottomRight)
				end,
				[OnEvent "MouseLeave"] = function()
